const test = require("node:test");
const assert = require("node:assert");

const { StablePriorityQueue } = require("./pq");

test("priority order", () => {
  const q = new StablePriorityQueue();
  q.push(5, "low");
  q.push(1, "high");
  q.push(3, "mid");
  assert.deepStrictEqual([q.pop(), q.pop(), q.pop()], ["high", "mid", "low"]);
});

test("equal priority is fifo across interleaved pushes and pops", () => {
  const q = new StablePriorityQueue();
  q.push(1, "first");
  q.push(2, "other");
  q.push(1, "second");
  assert.strictEqual(q.pop(), "first");
  q.push(1, "third");
  assert.deepStrictEqual([q.pop(), q.pop()], ["second", "third"]);
});

