class StablePriorityQueue {
  constructor() {
    this.items = [];
    this.counter = 0;
  }

  push(priority, item) {
    this.items.push({ priority, order: this.counter, item });
    this.counter -= 1;
    this.items.sort((a, b) => a.priority - b.priority || a.order - b.order);
  }

  pop() {
    return this.items.shift().item;
  }

  get length() {
    return this.items.length;
  }
}

module.exports = { StablePriorityQueue };
